<?php

declare(strict_types=1);require_once __DIR__.'/../../includes/module-admin.php';$pdo=cmsAdminModuleBoot('contact');$base='/admin/contact.php';
if($_SERVER['REQUEST_METHOD']==='POST'){cmsVerifyCsrf();$a=cmsStr($_POST['action']??'settings',30);if($a==='settings'){foreach(['contact_email','contact_phone','contact_whatsapp'] as $k)cmsSetSetting($k,cmsStr($_POST[$k]??'',255),$pdo);cmsSetSetting('contact_whatsapp_enabled',(string)cmsBool($_POST['contact_whatsapp_enabled']??0),$pdo);cmsAudit('contact.settings','site_settings');cmsAdminRedirect($base,'تم حفظ إعدادات التواصل.');}
$id=cmsInt($_POST['id']??0);if($id){if(in_array($a,['new','read','archived'],true)){$pdo->prepare('UPDATE contact_messages SET status=:s WHERE id=:id')->execute([':s'=>$a,':id'=>$id]);cmsAudit('contact.status','contact_messages',$id.':'.$a);cmsAdminRedirect($base,'تم تحديث الرسالة.');}if($a==='delete'){$pdo->prepare('DELETE FROM contact_messages WHERE id=:id')->execute([':id'=>$id]);cmsAudit('contact.delete','contact_messages',(string)$id);cmsAdminRedirect($base,'تم حذف الرسالة.');}}}
$status=in_array($_GET['status']??'all',['all','new','read','archived'],true)?$_GET['status']:'all';$sql='SELECT * FROM contact_messages'.($status==='all'?'':' WHERE status=:s').' ORDER BY id DESC LIMIT 250';$st=$pdo->prepare($sql);$st->execute($status==='all'?[]:[':s'=>$status]);$rows=$st->fetchAll();$settings=cmsSettings($pdo);$counts=[];foreach($pdo->query('SELECT status,COUNT(*) c FROM contact_messages GROUP BY status')->fetchAll() as $r)$counts[$r['status']]=$r['c'];cmsAdminHead('الرسائل والتواصل');cmsAdminSidebar('contact');cmsAdminTopbar('الرسائل والتواصل');?>
<div class="content"><?php if($m=cmsAdminMessage()):?><div class="alert"><?=cmsE($m)?></div><?php endif;?><section class="grid cards"><article class="card"><div class="muted">جديدة</div><div class="metric"><?=intval($counts['new']??0)?></div></article><article class="card"><div class="muted">مقروءة</div><div class="metric"><?=intval($counts['read']??0)?></div></article><article class="card"><div class="muted">مؤرشفة</div><div class="metric"><?=intval($counts['archived']??0)?></div></article></section><section class="card" style="margin-top:18px"><h2>قنوات التواصل</h2><form method="post"><?=cmsCsrfField()?><input type="hidden" name="action" value="settings"><div class="form-grid"><label class="field"><span>Email</span><input type="email" name="contact_email" value="<?=cmsE((string)($settings['contact_email']??''))?>"></label><label class="field"><span>الهاتف</span><input name="contact_phone" value="<?=cmsE((string)($settings['contact_phone']??''))?>"></label><label class="field"><span>WhatsApp</span><input name="contact_whatsapp" value="<?=cmsE((string)($settings['contact_whatsapp']??''))?>"></label><label class="module-row"><span>WhatsApp فعال</span><input class="check" type="checkbox" name="contact_whatsapp_enabled" value="1" <?=cmsChecked($settings['contact_whatsapp_enabled']??0)?>></label></div><button class="btn primary" style="margin-top:14px">حفظ</button></form></section><section class="card" style="margin-top:18px"><div class="toolbar"><div class="actions"><a class="btn <?=$status==='all'?'primary':''?>" href="?status=all">الكل</a><a class="btn <?=$status==='new'?'primary':''?>" href="?status=new">جديدة</a><a class="btn <?=$status==='read'?'primary':''?>" href="?status=read">مقروءة</a><a class="btn <?=$status==='archived'?'primary':''?>" href="?status=archived">مؤرشفة</a></div></div><div class="table-wrap"><table class="table"><thead><tr><th>المرسل</th><th>الرسالة</th><th>الحالة</th><th>التاريخ</th><th>إجراء</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=cmsE($r['name'])?></strong><div class="muted"><?=cmsE((string)$r['email'])?> <?=cmsE((string)$r['phone'])?></div></td><td><?=nl2br(cmsE($r['message']))?><?php if($r['subject']):?><div class="muted"><?=cmsE($r['subject'])?></div><?php endif;?></td><td><span class="pill"><?=cmsE($r['status'])?></span></td><td><?=cmsE($r['created_at'])?></td><td><form method="post" class="actions"><?=cmsCsrfField()?><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn" name="action" value="read">مقروءة</button><button class="btn" name="action" value="archived">أرشفة</button><button class="btn danger" name="action" value="delete" onclick="return confirm('حذف الرسالة؟')">حذف</button></form></td></tr><?php endforeach;?></tbody></table></div><?php if(!$rows):?><div class="empty">لا توجد رسائل.</div><?php endif;?></section></div><?php cmsAdminEnd();
